insert into public.roots (key, icon, name, kind, min_age, about, protects, academic, sources, position) values
('fear_not_enough','🫥','Fear of not being enough','fear',7,'A deep worry: "I''m not good enough, not loved enough, not as good as them." Some hide it with silence, some with jokes, some with showing off.','Being loved for who you are, not only for results; gratitude; small wins; comparing yourself with your own yesterday.','Insecurity and shame-proneness: a fragile or contingent sense of self-worth. A common vulnerability behind envy, social anxiety, perfectionism and both forms of narcissism (grandiosity as a defence).',array['Crocker, J., & Park, L. E. (2004). The costly pursuit of self-esteem. Psychological Bulletin, 130(3), 392–414.','Tangney, J. P., & Dearing, R. L. (2002). Shame and Guilt. Guilford Press.']::text[],0),
('fear_losing','🚪','Fear of losing someone','fear',7,'Being afraid that the people you love will leave, or love someone else more.','Reliable, warm love; keeping promises; learning that people can love more than one person.','Attachment insecurity (especially anxious attachment): hyperactivated fears of rejection and abandonment, linked to jealousy, dependency and unstable relationships.',array['Bowlby, J. (1969). Attachment and Loss, Vol. 1: Attachment. Basic Books.','Mikulincer, M., & Shaver, P. R. (2007). Attachment in Adulthood. Guilford Press.']::text[],1),
('fear_punishment','😨','Fear of punishment','fear',6,'Being so afraid of getting in trouble that hiding the truth feels safer.','Adults who stay calm when they hear the truth, and praise honesty even when the news is bad.','Punitive environments increase children''s lying to avoid sanctions; non-punitive responses to honesty increase truth-telling.',array['Talwar, V., & Lee, K. (2011). A punitive environment fosters children''s dishonesty. Child Development, 82(6), 1751–1758.']::text[],2),
('fear_chaos','🌪️','Fear of things going out of control','fear',9,'Feeling that if everything isn''t perfect and in order, something bad will happen.','Learning that "good enough" is OK, small safe mistakes, and flexible plans.','Intolerance of uncertainty and need for control: associated with perfectionism, rigidity and obsessive-compulsive features.',array['Dugas, M. J., Gagnon, F., Ladouceur, R., & Freeston, M. H. (1998). Generalized anxiety disorder: a preliminary test of a conceptual model. Behaviour Research and Therapy, 36(2), 215–226.']::text[],3),
('fear_being_hurt','🛡️','Fear of being hurt (attack first)','fear',7,'Feeling unsafe, so you strike first, get angry fast, or trust nobody.','Feeling safe at home and school; naming feelings; calm adults who don''t attack back.','Threat sensitivity and hostile attribution bias: interpreting ambiguous acts as hostile and responding with reactive aggression.',array['Dodge, K. A. (1980). Social cognition and children''s aggressive behavior. Child Development, 51(1), 162–170.']::text[],4),
('scarcity_fear','🥧','Fear there isn''t enough','fear',8,'Feeling that there aren''t enough good things, chances or love for everyone, so every win of someone else feels like your loss.','An abundance mindset, gratitude, and seeing that other people''s success opens doors instead of closing them.','Zero-sum and scarcity beliefs: perceiving resources and success as fixed, so others'' gains are experienced as one''s losses; associated with envy and competitiveness.',array['Różycka-Tran, J., Boski, P., & Wojciszke, B. (2015). Belief in a zero-sum game as a social axiom. Journal of Cross-Cultural Psychology, 46(4), 525–548.']::text[],5),
('learned_rewarded','🍬','It worked before (learned)','learned',6,'A bad habit grows when it gets results: shouting got the toy, lying avoided trouble, silence made Mum give in.','Making sure bad behaviour doesn''t "win", and good behaviour is noticed.','Operant learning: behaviours followed by reinforcement (gaining something or escaping something unpleasant) become more frequent.',array['Skinner, B. F. (1953). Science and Human Behavior. Macmillan.']::text[],6),
('copied_models','👀','Copied from others','learned',6,'Children copy what they see: at home, at school, on screens.','Good examples nearby, and talking about what we see on screens.','Observational (social) learning: aggression and other behaviours are acquired by watching models, especially when the model is rewarded.',array['Bandura, A., Ross, D., & Ross, S. A. (1961). Transmission of aggression through imitation of aggressive models. Journal of Abnormal and Social Psychology, 63(3), 575–582.']::text[],7),
('situation_power','👮','Power with nobody checking','situation',12,'Even good people can do bad things when they get power over others and nobody is watching.','Rules that apply to everyone, someone checking, and the courage to say "no".','Situational and systemic forces (role, authority, anonymity, group pressure) can override individual dispositions.',array['Milgram, S. (1963). Behavioral study of obedience. Journal of Abnormal and Social Psychology, 67(4), 371–378.','Zimbardo, P. (2007). The Lucifer Effect. Random House.']::text[],8),
('trauma','⚡','Something terrible happened','trauma',10,'A very frightening or painful event. This is not weakness: it can happen to the strongest person.','Safety, people who listen, and doctors or therapists.','Exposure to traumatic events is a necessary condition for PTSD and a risk factor for several other difficulties; outcomes depend heavily on support afterwards.',array['American Psychiatric Association (2022). DSM-5-TR.']::text[],9),
('born_different','🧬','Born with a brain that works differently','born',8,'Some differences are there from birth. They are not weakness and not anyone''s fault.','Understanding, patience, and help that fits the person.','Neurodevelopmental differences (such as autism) have strong genetic and early-developmental contributions.',array['American Psychiatric Association (2022). DSM-5-TR.']::text[],10),
('low_fear','🧊','Very little fear (no brake)','born',14,'Some people feel almost no fear, even of punishment, so nothing stops them. The opposite of most problems here!','Clear limits and consequences early; teaching empathy directly.','Fearlessness theory: low fear and weak responses to punishment cues are associated with psychopathy and antisocial behaviour.',array['Lykken, D. T. (1957). A study of anxiety in the sociopathic personality. Journal of Abnormal and Social Psychology, 55(1), 6–10.']::text[],11)
